import json
with open('factors/days_since_high_60.json') as f:
    d = json.load(f)
# Show keys and non-signal parts
def summarize(o, depth=0, maxd=3):
    if depth > maxd: return
    if isinstance(o, dict):
        for k,v in o.items():
            if k in ('signal','signal_artifact','history','values','series','ts','artifacts'):
                print('  '*depth + f'{k}: <{type(v).__name__} {len(v) if hasattr(v,\"__len__\") else \"\"}>')
            else:
                print('  '*depth + f'{k}:')
                summarize(v, depth+1, maxdepth)
    elif isinstance(o, list):
        print('  '*depth + f'list[{len(o)}]')
        if o: summarize(o[0], depth+1, maxdepth)
    else:
        print('  '*depth + repr(o)[:120])
summarize(d)
"

